// Get error data from the Error Trigger
const errorData = $input.first().json;

const execution = errorData.execution || {};
const error = errorData.executionError || {};
const workflowInfo = errorData.workflow || {};

const workflowName = workflowInfo.name || 'Unknown Workflow';
const workflowId = workflowInfo.id || 'N/A';
const executionId = execution.id || 'N/A';
const errorNode = error.node ? error.node.name || error.node : 'Unknown Node';
const errorMessage = error.message || 'No error message';
const timestamp = execution.startedAt || execution.finishedAt || new Date().toISOString();

// Truncate long error messages to avoid Telegram 4096 char limit
const truncate = (str, maxLen = 3000) => {
  if (!str) return 'N/A';
  const s = String(str);
  return s.length > maxLen ? s.substring(0, maxLen) + '...' : s;
};

// Build execution data string
const executionData = errorData.executionData ? JSON.stringify(errorData.executionData, null, 2) : 'N/A';

// Count total nodes in execution
const nodeCount = executionData !== 'N/A' && errorData.executionData
  ? Object.keys(errorData.executionData).length
  : 'N/A';

// Build the message
const message = `
🔴 <b>Workflow Error Alert</b>

📋 <b>Workflow:</b> ${workflowName}
🆔 <b>Workflow ID:</b> <code>${workflowId}</code>
⏰ <b>Time:</b> ${new Date(timestamp).toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' })}

⚠️ <b>Error Node:</b> ${errorNode}
❌ <b>Error Message:</b>
<code>${truncate(errorMessage, 1000)}</code>

🔗 <b>Execution:</b> <code>${truncate(executionId, 50)}</code>
📊 <b>Nodes in execution:</b> ${nodeCount}

📝 <b>Full Execution Data:</b>
<code>${truncate(executionData, 2000)}</code>
`.trim();

return [{
  json: {
    workflowName,
    workflowId,
    executionId,
    errorNode,
    errorMessage: truncate(errorMessage, 500),
    timestamp,
    message
  }
}];

// Audit log for the notification
const data = $input.first().json;

const logEntry = {
  workflow_name: data.workflowName,
  workflow_id: data.workflowId,
  execution_id: data.executionId,
  error_node: data.errorNode,
  error_message: data.errorMessage,
  notified_at: data.timestamp
};

console.log('Error notification sent:', JSON.stringify(logEntry, null, 2));

return [{ json: { ...data, logged: true, logEntry } }];
